10	export const TelemetryEventSchema = z.object({
11	  event: z.enum([
12	    'assertion_used',
13	    'command_used',
14	    'eval setup',
15	    'eval_ran',
16	    'feature_used',
17	    'funnel',
18	    'redteam discover',
19	    'redteam generate',
20	    'redteam init',
21	    'redteam poison',
22	    'redteam report',
23	    'redteam run',
24	    'redteam setup',
25	    'webui_action',
26	    'webui_api',
27	    'webui_page_view',
28	  ]),
29	  packageVersion: z.string().optional().prefault(VERSION),
30	  properties: z.record(
31	    z.string(),
32	    z.union([z.string(), z.number(), z.boolean(), z.array(z.string())]),
33	  ),
34	});
35	type TelemetryEvent = z.infer<typeof TelemetryEventSchema>;
36	export type TelemetryEventTypes = TelemetryEvent['event'];
37	export type EventProperties = TelemetryEvent['properties'];
38	
39	let posthogClient: PostHog | null = null;
40	let isShuttingDown = false;
41	
42	function getPostHogClient(): PostHog | null {
43	  if (getEnvBool('PROMPTFOO_DISABLE_TELEMETRY') || getEnvBool('IS_TESTING')) {
44	    return null;
45	  }
46	
47	  if (posthogClient === null && POSTHOG_KEY) {
48	    try {
49	      posthogClient = new PostHog(POSTHOG_KEY, {
50	        host: EVENTS_ENDPOINT,
51	        fetch: fetchWithProxy,
52	        // Disable automatic flush interval to prevent keeping the event loop alive.
53	        // Without this, PostHog's internal setInterval keeps the Node.js event loop
54	        // alive indefinitely, causing processes that import promptfoo to hang.
55	        // Events are still sent immediately via explicit flush() calls after each capture.
56	        // See: https://github.com/promptfoo/promptfoo/issues/5893
57	        flushInterval: 0,
58	      });
59	    } catch {
60	      posthogClient = null;
61	    }
62	  }
63	  return posthogClient;
64	}
