66	const TELEMETRY_TIMEOUT_MS = 1000;
67	
68	export class Telemetry {
69	  private telemetryDisabledRecorded = false;
70	  private id: string;
71	
72	  constructor() {
73	    this.id = getUserId();
74	    void this.identify();
75	  }
76	
77	  private getPersonProperties(ciFlag: boolean) {
78	    const personProperties = {
79	      ...getUserAuthInfo(),
80	      isRunningInCi: ciFlag,
81	    };
82	    return personProperties;
83	  }
84	
85	  async identify() {
86	    if (this.disabled || getEnvBool('IS_TESTING')) {
87	      return;
88	    }
89	
90	    const client = getPostHogClient();
91	    if (client) {
92	      try {
93	        const personProperties = this.getPersonProperties(isCI());
94	        client.identify({
95	          distinctId: this.id,
96	          properties: personProperties,
97	        });
98	        client.flush().catch(() => {
99	          // Silently ignore flush errors
100	        });
101	      } catch (error) {
102	        logger.debug(`PostHog identify error: ${error}`);
103	      }
104	    }
105	  }
106	
107	  get disabled() {
108	    return getEnvBool('PROMPTFOO_DISABLE_TELEMETRY');
109	  }
110	
111	  private recordTelemetryDisabled() {
112	    if (!this.telemetryDisabledRecorded) {
113	      this.sendEvent('feature_used', { feature: 'telemetry disabled' });
114	      this.telemetryDisabledRecorded = true;
115	    }
116	  }
117	
118	  record(eventName: TelemetryEventTypes, properties: EventProperties): void {
119	    if (this.disabled) {
120	      this.recordTelemetryDisabled();
121	    } else {
122	      this.sendEvent(eventName, properties);
123	    }
124	  }
125	
126	  private sendEvent(eventName: TelemetryEventTypes, properties: EventProperties): void {
127	    const ciFlag = isCI();
128	    const personProperties = this.getPersonProperties(ciFlag);
129	    const propertiesWithMetadata = {
130	      ...properties,
131	      packageVersion: VERSION,
132	      isRunningInCi: ciFlag,
133	    };
134	
135	    const client = getPostHogClient();
136	    if (client && !getEnvBool('IS_TESTING')) {
137	      try {
138	        client.capture({
139	          distinctId: this.id,
140	          event: eventName,
141	          properties: {
142	            ...propertiesWithMetadata,
143	            // Mirror person properties on every event so dashboard filters on person
144	            // properties (e.g. excluding CI traffic) work even when the user only
145	            // ever fires real events and never the auto-generated $identify.
146	            $set: personProperties,
147	          },
148	        });
149	        client.flush().catch(() => {
150	          // Silently ignore flush errors
151	        });
152	      } catch (error) {
153	        logger.debug(`PostHog capture error: ${error}`);
154	      }
155	    }
156	
157	    fetchWithProxy(R_ENDPOINT, {
158	      method: 'POST',
159	      headers: {
160	        'Content-Type': 'application/json',
161	      },
162	      body: JSON.stringify({
163	        event: eventName,
164	        environment: getEnvString('NODE_ENV', 'development'),
165	        email: personProperties.email,
166	        meta: {
167	          user_id: this.id,
168	          ...propertiesWithMetadata,
169	        },
170	      }),
171	    }).catch(() => {
172	      // pass
173	    });
174	  }
175	
176	  async shutdown(): Promise<void> {
177	    // Guard against multiple shutdown calls (from beforeExit + explicit shutdown in main.ts)
178	    if (isShuttingDown) {
179	      return;
180	    }
181	
182	    const client = getPostHogClient();
183	    if (!client) {
184	      // No client to shut down - don't set the flag so future shutdowns work
185	      // if telemetry becomes enabled (e.g., in test harnesses)
186	      return;
187	    }
188	
189	    isShuttingDown = true;
190	    try {
191	      await client.shutdown();
192	    } catch (error) {
193	      logger.debug(`PostHog shutdown error: ${error}`);
194	    }
195	  }
196	
197	  /**
198	   * This is a separate endpoint to save consent used only for redteam data synthesis for "harmful" plugins.
199	   */
200	  async saveConsent(email: string, metadata?: Record<string, string>): Promise<void> {
201	    try {
202	      const response = await fetchWithTimeout(
203	        CONSENT_ENDPOINT,
204	        {
205	          method: 'POST',
206	          headers: {
207	            'Content-Type': 'application/json',
208	          },
209	          body: JSON.stringify({ email, metadata }),
210	        },
211	        TELEMETRY_TIMEOUT_MS,
212	      );
213	
214	      if (!response.ok) {
215	        throw new Error(`Failed to save consent: ${response.statusText}`);
216	      }
217	    } catch (err) {
218	      logger.debug(`Failed to save consent: ${(err as Error).message}`);
219	    }
220	  }
221	}
